import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const b=JSON.parse('{"title":"附录 C 内置技能速查表","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/附录/附录 C 内置技能速查表.md","filePath":"bluebook/附录/附录 C 内置技能速查表.md"}'),r={name:"bluebook/附录/附录 C 内置技能速查表.md"};function n(s,t,c,i,l,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="附录-c-内置技能速查表" tabindex="-1">附录 C 内置技能速查表 <a class="header-anchor" href="#附录-c-内置技能速查表" aria-label="Permalink to &quot;附录 C 内置技能速查表&quot;">​</a></h1><blockquote><p>平台内置 <strong>33 个技能条目</strong>（技能包版本 <code>0.1.33</code>）。其中 <code>auto-inject</code> 为自动注入层，内含 5 个子技能。用法：先查 C1 定位，再看对应小节，最后一句话调起来。</p></blockquote><h2 id="c1-按需求反查" tabindex="-1">C1 按需求反查 <a class="header-anchor" href="#c1-按需求反查" aria-label="Permalink to &quot;C1 按需求反查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想做什么</th><th>用哪个技能</th><th>详见</th></tr></thead><tbody><tr><td>画一张图</td><td>DALL·E 3 / FLUX / Midjourney / SD</td><td>C2</td></tr><tr><td>生成一段视频</td><td>豆包 Seedance / 可灵 / 海螺 / Runway / Sora</td><td>C3</td></tr><tr><td>出一份 Word / Excel / PPT</td><td>officecli 系列</td><td>C4</td></tr><tr><td>要一份专业交付物（论文/看板/财务模型/路演）</td><td>场景层技能</td><td>C4</td></tr><tr><td>画流程图 / 时序图</td><td>mermaid</td><td>C5</td></tr><tr><td>处理 PDF</td><td>pdf</td><td>C5</td></tr><tr><td>让任务按时自动跑</td><td>cron</td><td>C6</td></tr><tr><td>造一个新技能</td><td>skill-creator</td><td>C6</td></tr><tr><td>把文件发到手机/微信</td><td>weixin-file-send</td><td>C7</td></tr><tr><td>发小红书 / X 帖子</td><td>xiaohongshu-recruiter / x-recruiter</td><td>C7</td></tr><tr><td>找并安装新能力</td><td>moma-setup-guide</td><td>C8</td></tr><tr><td>手机远程用</td><td>momawork-webui-setup</td><td>C8</td></tr></tbody></table><h2 id="c2-图像生成-4-个" tabindex="-1">C2 图像生成（4 个） <a class="header-anchor" href="#c2-图像生成-4-个" aria-label="Permalink to &quot;C2 图像生成（4 个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能</th><th>模型</th><th>最擅长</th><th>提示词语言</th><th>关键参数</th></tr></thead><tbody><tr><td><code>dalle3-image-gen</code></td><td>DALL·E 3</td><td>语义准确、复杂描述</td><td><strong>英文优先</strong></td><td>尺寸 1024²/1792×1024/1024×1792；质量 standard·hd；风格 vivid·natural</td></tr><tr><td><code>flux-image-gen</code></td><td>FLUX</td><td><strong>文字渲染</strong>、复杂构图、写实</td><td>中英</td><td>适合带标题的海报/封面</td></tr><tr><td><code>midjourney-image-gen</code></td><td>Midjourney</td><td>艺术化、美学质感</td><td>中英</td><td>风格化参数</td></tr><tr><td><code>stable-diffusion-image-gen</code></td><td>Stable Diffusion</td><td>精细控制、图生图</td><td>正/负向提示词</td><td>反复微调同一画面</td></tr></tbody></table><p><strong>调用示例：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>做一张公众号封面图，深蓝色科技风，右侧留出标题位置，竖版</span></span></code></pre></div><p><strong>六要素提示词骨架</strong>（通用）：主体 + 动作 + 环境 + 光线 + 构图 + 风格。</p><h2 id="c3-视频生成-7-个" tabindex="-1">C3 视频生成（7 个） <a class="header-anchor" href="#c3-视频生成-7-个" aria-label="Permalink to &quot;C3 视频生成（7 个）&quot;">​</a></h2><blockquote><p>⚠️ 全部 7 个技能共享同一条硬规则：<strong>先输出 2-3 版脚本 → 等你确认 → 才生成</strong>。这不是卡顿，是设计。</p></blockquote><table tabindex="0"><thead><tr><th>技能</th><th>模型</th><th>语言</th><th>特点</th></tr></thead><tbody><tr><td><code>doubao-seedance-video-gen</code></td><td>豆包 Seedance 2.0</td><td>中文</td><td>综合能力最均衡</td></tr><tr><td><code>doubao-seedance-fast-video-gen</code></td><td>Seedance 2.0 Fast</td><td>中文</td><td>快速出片，适合试想法</td></tr><tr><td><code>doubao-seedance-mini-video-gen</code></td><td>Seedance 2.0 Mini</td><td>中文</td><td>轻量短视频</td></tr><tr><td><code>kling-video-gen</code></td><td>可灵 1.6</td><td>中文</td><td>中文语义、人物表现好</td></tr><tr><td><code>minimax-hailuo-video-gen</code></td><td>海螺 2.3</td><td>中文</td><td>画面质感与动态自然</td></tr><tr><td><code>runway-video-gen</code></td><td>Runway Gen-3/Gen-4</td><td><strong>英文</strong></td><td>电影级镜头控制</td></tr><tr><td><code>sora-video-gen</code></td><td>Sora</td><td><strong>英文</strong></td><td>写实与物理一致性</td></tr></tbody></table><p><strong>脚本六要素</strong>：主体 · 动作 · 场景 · <strong>镜头</strong> · <strong>光影</strong> · 画质。</p><h2 id="c4-文档、表格与演示-10-个" tabindex="-1">C4 文档、表格与演示（10 个） <a class="header-anchor" href="#c4-文档、表格与演示-10-个" aria-label="Permalink to &quot;C4 文档、表格与演示（10 个）&quot;">​</a></h2><h3 id="基础层-通用能力" tabindex="-1">基础层（通用能力） <a class="header-anchor" href="#基础层-通用能力" aria-label="Permalink to &quot;基础层（通用能力）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>用途</th></tr></thead><tbody><tr><td><code>officecli-docx</code></td><td>读写改 <code>.docx</code>：报告、方案、信函、备忘录、提案</td></tr><tr><td><code>officecli-xlsx</code></td><td>表格、公式、图表、透视表；CSV → Excel</td></tr><tr><td><code>officecli-pptx</code></td><td>演示文稿：创建、编辑、合并拆分、模板、备注</td></tr></tbody></table><h3 id="场景层-继承基础层全部规则" tabindex="-1">场景层（继承基础层全部规则） <a class="header-anchor" href="#场景层-继承基础层全部规则" aria-label="Permalink to &quot;场景层（继承基础层全部规则）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能</th><th>家族</th><th>用途</th></tr></thead><tbody><tr><td><code>officecli-word-form</code></td><td>Word（<strong>独立技能</strong>）</td><td>可填写表单：SDT 内容控件 + 文档保护 + 邮件合并占位符</td></tr><tr><td><code>officecli-academic-paper</code></td><td>Word</td><td>学术论文：APA/Chicago/IEEE/MLA、编号公式、交叉引用、参考文献</td></tr><tr><td><code>officecli-data-dashboard</code></td><td>Excel</td><td>数据看板：KPI 卡片 + 多图表 + 迷你图 + 条件格式</td></tr><tr><td><code>officecli-financial-model</code></td><td>Excel</td><td>财务模型：三表模型、DCF、LBO、敏感性分析、单位经济</td></tr><tr><td><code>officecli-pitch-deck</code></td><td>PPT</td><td>融资路演：种子轮 / A / B / C 轮、SAFE、可转债</td></tr><tr><td><code>morph-ppt</code></td><td>PPT</td><td>跨页平滑动画（Morph）：形状生长、移动、旋转</td></tr><tr><td><code>morph-ppt-3d</code></td><td>PPT</td><td>morph + <strong>GLB 三维模型</strong> + 电影级镜头语言</td></tr></tbody></table><p><strong>分层判断口诀</strong>：通用交付用基础层，专业交付用场景层。</p><h2 id="c5-图表与-pdf-2-个" tabindex="-1">C5 图表与 PDF（2 个） <a class="header-anchor" href="#c5-图表与-pdf-2-个" aria-label="Permalink to &quot;C5 图表与 PDF（2 个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能</th><th>能力</th></tr></thead><tbody><tr><td><code>mermaid</code></td><td>流程图、时序图、状态图、类图、ER 图；输出 <strong>SVG</strong>（文档/PPT 用）或 <strong>ASCII</strong>（聊天/终端用）</td></tr><tr><td><code>pdf</code></td><td>文本与表格提取、创建、合并拆分、<strong>表单填写</strong>、批量处理</td></tr></tbody></table><h2 id="c6-平台与自动化-自动注入层-auto-inject-内含-5-个" tabindex="-1">C6 平台与自动化（自动注入层 <code>auto-inject</code>，内含 5 个） <a class="header-anchor" href="#c6-平台与自动化-自动注入层-auto-inject-内含-5-个" aria-label="Permalink to &quot;C6 平台与自动化（自动注入层 \`auto-inject\`，内含 5 个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>子技能</th><th>作用</th><th>你要知道的规则</th></tr></thead><tbody><tr><td><code>cron</code></td><td>定时任务：创建、查询、更新</td><td><strong>每个会话只有一个任务</strong>；先查后建</td></tr><tr><td><code>skill-creator</code></td><td>指导创建有效的技能</td><td>写 Skill 时自动生效</td></tr><tr><td><code>momawork-skills</code></td><td>技能管理</td><td>技能的新增/更新/组织</td></tr><tr><td><code>officecli</code></td><td>Office CLI 底座</td><td>C4 所有 Office 技能的底层工具</td></tr><tr><td><code>superpowers</code></td><td>能力增强</td><td>自动生效，无需调用</td></tr></tbody></table><blockquote><p>这一层<strong>不需要你手动加载</strong>——平台会在合适场景自动挂上。所以你能&quot;没装定时任务技能也能定时&quot;。</p></blockquote><p><strong>定时任务话术：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每天早上 9 点，抓取 AI 行业动态整理成 5 条摘要</span></span>
<span class="line"><span>看看我现在的定时任务</span></span>
<span class="line"><span>把那个任务改成每天下午 6 点</span></span></code></pre></div><h2 id="c7-投递与内容平台-3-个" tabindex="-1">C7 投递与内容平台（3 个） <a class="header-anchor" href="#c7-投递与内容平台-3-个" aria-label="Permalink to &quot;C7 投递与内容平台（3 个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能</th><th>用途</th><th>话术示例</th></tr></thead><tbody><tr><td><code>weixin-file-send</code></td><td>把本地文件/图片发回给你</td><td>&quot;把文件发给我&quot; / &quot;发给我&quot;</td></tr><tr><td><code>xiaohongshu-recruiter</code></td><td>小红书发布：极客风封面图 + 详情图 + 自动发布</td><td>&quot;发布一个前端工程师招聘到小红书&quot;</td></tr><tr><td><code>x-recruiter</code></td><td>X (x.com) 发布：文案规范 + 图片提示 + 发布脚本</td><td>&quot;发一条 AI 岗位招聘到 X&quot;</td></tr></tbody></table><blockquote><p>发布类技能需要<strong>你扫码登录</strong>——账号安全永远在你自己手里。</p></blockquote><h2 id="c8-环境与配置-4-个" tabindex="-1">C8 环境与配置（4 个） <a class="header-anchor" href="#c8-环境与配置-4-个" aria-label="Permalink to &quot;C8 环境与配置（4 个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能</th><th>用途</th></tr></thead><tbody><tr><td><code>moma-setup-guide</code></td><td><strong>能力市场向导</strong>：从 5 个市场（专家/技能/MCP/模板/Agent）搜索并安装，来源含 MomaWork 官方、npm、PyPI、Smithery、GitHub</td></tr><tr><td><code>momawork-webui-setup</code></td><td>WebUI 远程访问配置：局域网 / Tailscale / 服务器部署；Windows·macOS·Linux·Android</td></tr><tr><td><code>openclaw-setup</code></td><td>OpenClaw 个人 AI 助手的安装、部署、配置与排障</td></tr><tr><td><code>star-office-helper</code></td><td>可视化配套（默认 Star-Office-UI）：安装、启动、连接、排障</td></tr></tbody></table><p><strong>发一句话就能用：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我需要一个处理小红书内容的技能，帮我找找并装上</span></span>
<span class="line"><span>帮我配置 WebUI，我想在手机上用</span></span></code></pre></div><h2 id="c9-创作与玩法-2-个" tabindex="-1">C9 创作与玩法（2 个） <a class="header-anchor" href="#c9-创作与玩法-2-个" aria-label="Permalink to &quot;C9 创作与玩法（2 个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能</th><th>是什么</th></tr></thead><tbody><tr><td><code>moltbook</code></td><td><strong>AI 代理的社交网络</strong>：发帖、评论、点赞、建社区</td></tr><tr><td><code>story-roleplay</code></td><td>角色扮演：解析 SillyTavern 兼容角色卡（PNG/WebP/JSON），关键词触发与动态更新</td></tr></tbody></table><h2 id="c10-一句话调用模板" tabindex="-1">C10 一句话调用模板 <a class="header-anchor" href="#c10-一句话调用模板" aria-label="Permalink to &quot;C10 一句话调用模板&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【生成图】做一张{用途}的图，{风格}，{尺寸方向}，{要/不要文字}</span></span>
<span class="line"><span>【生成视频】做一条{时长}{平台}视频，主题是{主题}，情绪{情绪}</span></span>
<span class="line"><span>【Word】写一份《{标题}》，输出 Word，{受众}{结构要求}</span></span>
<span class="line"><span>【表单】做一份{用途}表单，Word 格式，只有填写区可编辑</span></span>
<span class="line"><span>【看板】把{数据源}做成数据看板，包含{KPI 列表}</span></span>
<span class="line"><span>【财务模型】基于{数据}做一份{三表/DCF}模型，含敏感性分析</span></span>
<span class="line"><span>【PPT】把{内容}做成{页数}页 PPT，{受众}{风格}</span></span>
<span class="line"><span>【路演】做一份{轮次}融资路演 PPT，重点讲{核心卖点}</span></span>
<span class="line"><span>【图表】把{流程}画成{流程图/时序图}，输出 SVG</span></span>
<span class="line"><span>【PDF】从{文件}里提取表格，合并成一个 Excel</span></span>
<span class="line"><span>【定时】每天{时间}，{做什么}</span></span>
<span class="line"><span>【投递】把{文件}发给我</span></span>
<span class="line"><span>【市场】我需要{需求}，去市场找找并装上</span></span></code></pre></div><hr><blockquote><p>提示：技能包会随平台版本更新（当前 <code>0.1.33</code>）。升级后回看本附录，留意新增条目。</p></blockquote>`,39)])])}const u=d(r,[["render",n]]);export{b as __pageData,u as default};
